    const previous = node.isWord ? node.value : undefined;

    // If this is a new word, increment counts along the path
    if (!node.isWord) {
      this.#size += 1;
      let current = this.#root;
      for (const char of codePoints) {
        const cp = char.codePointAt(0);
        current = current.children.get(cp);
        current.wordCount += 1;
      }
